// SHA-256 / HMAC-SHA256 (FIPS 180-4, RFC 2104), so Slack signatures can be checked without `crypto`.

const K256 = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
